const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the location of Klyuchevskaya Sopka volcano.
    const volcanoPoint = ee.Geometry.Point([160.642, 56.057]);

    // Define the date of interest. This is a future date.
    const startDate = '2025-08-08';
    const endDate = '2025-08-09';

    // 2. Data Acquisition & Check
    // Use Sentinel-5P TROPOMI to detect Sulfur Dioxide (SO2), a tracer for volcanic plumes.
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
        .filterBounds(volcanoPoint)
        .filterDate(startDate, endDate)
        .select('SO2_column_number_density');

    // Check if any images exist for the specified future date.
    const imageCount = collection.size().getInfo();
    console.log(`Images found for ${startDate}: ${imageCount}`);

    // 3. Validation & Final Answer
    // Since the date is in the future, no images will be available.
    if (imageCount === 0) {
        console.log('Error: The specified date is in the future. No satellite data exists.');
        console.log('A'); // This line is for demonstration and will be replaced by the final answer tag
    } else {
        // This block will not be executed but is included for completeness.
        // If data existed, we would define two regions (east and west) to compare SO2 concentration.
        const eastBox = ee.Geometry.Rectangle([160.8, 55.8, 163.8, 56.3]); // East of the volcano
        const westBox = ee.Geometry.Rectangle([157.5, 55.8, 160.5, 56.3]); // West of the volcano

        const plumeImage = collection.mean();

        const eastMean = plumeImage.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: eastBox,
            scale: 1000,
            maxPixels: 1e9
        }).get('SO2_column_number_density');

        const westMean = plumeImage.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: westBox,
            scale: 1000,
            maxPixels: 1e9
        }).get('SO2_column_number_density');

        const eastVal = eastMean.getInfo();
        const westVal = westMean.getInfo();

        console.log(`Mean SO2 East: ${eastVal}`);
        console.log(`Mean SO2 West: ${westVal}`);

        if (eastVal === null || westVal === null) {
            console.log('B');
        } else if (eastVal > westVal) {
            console.log('A');
        } else {
            console.log('B');
        }
    }
}

